<template><section class="tasks-panel"><header class="task-toolbar"><h2>{{manager?'任务管理':'班长派发的任务'}}</h2><div class="toolbar-actions"><button @click="load" :disabled="busy">刷新</button><button v-if="manager && !readOnly" class="primary" :aria-expanded="createOpen" @click="createOpen=!createOpen">{{createOpen?'收起':'派发任务'}}</button></div></header>
<section v-if="manager && !readOnly && createOpen" class="task-create"><form @submit.prevent="create"><label>任务名称<input v-model="draft.title" required maxlength="150" placeholder="例如：排查各楼层压取机设备状态"></label><label>完成要求<textarea v-model="draft.instructions" required maxlength="4000" rows="3"></textarea></label><fieldset><legend>接收组长</legend><label v-for="m in members" :key="m.user_id" class="check"><input type="checkbox" :value="m.user_id" v-model="draft.userIds">{{m.floor}} 楼 · {{m.name}}</label></fieldset><div class="pair"><label>截止日期<input type="date" v-model="draft.dueDate" :min="today" required></label><label>验证材料<select v-model="draft.evidenceMode"><option value="either">截图或在线文档链接</option><option value="photo">必须上传截图</option></select></label></div><label>关联工作内容（可选）<select v-model="draft.dutyId"><option value="">放入指令性工作</option><option v-for="d in duties" :key="d.id" :value="d.id">{{d.category}} · {{d.title}}</option></select></label><button class="primary" :disabled="busy||!draft.userIds.length">派发给 {{draft.userIds.length}} 位组长</button></form></section>
<button v-if="focusId" @click="$emit('clear-focus')">← 返回全部任务</button><div v-else class="task-filter"><button v-for="f in filters" :key="f.key" :class="{active:filter===f.key}" @click="filter=f.key;page=1;load()">{{f.label}}<span class="filter-count">{{count(f.key)}}</span></button></div><p v-if="error" role="alert">任务加载失败，请刷新重试。</p><p v-else-if="!visible.length">暂无此类任务</p>
<article v-for="a in visible" :key="a.id" class="assigned-task"><header><h3>{{a.title}}</h3><span class="task-status" :class="[a.status,{late:a.overdue}]">{{labels[a.status]}}{{a.overdue?' · 已逾期':''}}</span></header><small>{{manager?`${a.name} · ${a.floor} 楼 · `:''}}截止 {{a.due_date}}</small><p class="instructions">{{a.instructions}}</p><p v-if="a.feedback" class="feedback">班长意见：{{a.feedback}}</p>
<div class="files"><div v-for="f in a.files" :key="f.id"><WorkPhoto :id="f.id" task/><button v-if="!manager&&['pending','returned'].includes(a.status)" :disabled="busy" @click="removeFile(f.id)">移除</button></div></div>
<form v-if="!manager&&['pending','returned'].includes(a.status)" @submit.prevent="respond(a)"><label>检查结果<select v-model="answers[a.id].result" required><option value="">请选择</option><option>正常</option><option>异常</option></select></label><label>说明{{answers[a.id].result==='异常'?'（必填）':'（选填）'}}<textarea v-model="answers[a.id].note" :required="answers[a.id].result==='异常'" maxlength="4000"></textarea></label><label>在线文档链接<input type="url" v-model="answers[a.id].reference" placeholder="https://…"></label><label>上传验证截图<input type="file" accept="image/jpeg,image/png" :disabled="busy||a.files.length>=6" @change="upload(a,$event)"></label><button class="primary" :disabled="busy">提交班长验收</button></form>
<template v-else><b class="task-result-label">{{a.result}}</b><p v-if="a.note">{{a.note}}</p><a v-if="/^https?:\/\//i.test(a.reference||'')" :href="a.reference" target="_blank" rel="noopener">在线验证材料 ↗</a></template>
<div v-if="manager && !readOnly" class="review"><template v-if="a.status==='submitted'"><label>验收意见<input v-model="answers[a.id].feedback" placeholder="退回时必填" maxlength="2000"></label><button :disabled="busy" @click="review(a,'return')">退回补充</button><button class="primary" :disabled="busy" @click="review(a,'accept')">验收通过</button></template><details v-if="a.status!=='accepted'" class="deadline-edit"><summary>调整截止日期</summary><div class="deadline-fields"><input aria-label="新的截止日期" type="date" :min="today" v-model="answers[a.id].dueDate"><button :disabled="busy" @click="review(a,'extend')">保存延期</button></div></details></div></article><div v-if="total>50" class="pagination"><button :disabled="busy||page<=1" @click="page--;load()">上一页</button><span>第 {{page}} 页 · 共 {{total}} 条</span><button :disabled="busy||page*50>=total" @click="page++;load()">下一页</button></div></section></template>
<script setup>
import {ref,onMounted,onBeforeUnmount,watch} from 'vue'
import {computed} from 'vue'
import {ElMessage} from 'element-plus'
import {work} from '../api/work'
import WorkPhoto from './WorkPhoto.vue'
const props=defineProps({manager:Boolean,readOnly:Boolean,members:Array,duties:Array,focusId:[Number,String]}),emit=defineEmits(['change','clear-focus'])
const today=new Date(Date.now()+8*3600000).toISOString().slice(0,10),rows=ref([]),busy=ref(false),error=ref(false),answers=ref({}),filter=ref(props.manager?'submitted':'open')
const labels={pending:'待完成',returned:'待补充',submitted:'待验收',accepted:'已验收'},filters=[{key:'open',label:'待处理'},{key:'submitted',label:'待验收'},{key:'accepted',label:'已验收'},{key:'all',label:'全部'}]
const createOpen=ref(false),page=ref(1),total=ref(0),counts=ref({})
const draft=ref({title:'',instructions:'',dueDate:today,evidenceMode:'either',userIds:[],dutyId:'directive_tasks'})
const matches=(a,key)=>key==='all'||(key==='open'?['pending','returned'].includes(a.status):a.status===key)
const visible=computed(()=>rows.value.filter(a=>props.focusId||matches(a,filter.value)))
const count=key=>counts.value[key]||0
let loadSequence=0
async function load(){const sequence=++loadSequence;try{if(props.focusId){const r=await work.get(`/tasks/${props.focusId}`);if(sequence!==loadSequence)return;rows.value=[r.data];total.value=1;answers.value[r.data.id]={result:r.data.result||'',note:r.data.note||'',reference:r.data.reference||'',feedback:'',dueDate:r.data.due_date,...answers.value[r.data.id]};error.value=false;emit('change');return}const r=await work.get('/tasks',{params:{page:page.value,status:filter.value}});if(sequence!==loadSequence)return;rows.value=r.data.items;total.value=r.data.total;counts.value=r.data.counts;for(const a of rows.value)answers.value[a.id]={result:a.result||'',note:a.note||'',reference:a.reference||'',feedback:'',dueDate:a.due_date,...answers.value[a.id]};error.value=false;emit('change',r.data)}catch{if(sequence===loadSequence)error.value=true}}
async function act(fn){if(busy.value)return;busy.value=true;try{await fn();await load()}catch(e){if(e?.message&&!e?.response)ElMessage.error(e.message)}finally{busy.value=false}}
async function create(){await act(async()=>{await work.post('/tasks',draft.value);draft.value={...draft.value,title:'',instructions:'',userIds:[]};createOpen.value=false;ElMessage.success('任务已派发')})}
async function respond(a){await act(async()=>{await work.post(`/tasks/${a.id}/respond`,{...answers.value[a.id],revision:a.revision});ElMessage.success('已提交验收')})}
async function review(a,action){await act(async()=>{await work.post(`/tasks/${a.id}/review`,{...answers.value[a.id],revision:a.revision,action});ElMessage.success('任务已更新')})}
async function upload(a,event){const file=event.target.files?.[0];event.target.value='';if(!file)return;await act(async()=>{if(!['image/jpeg','image/png'].includes(file.type)||file.size>25*1024*1024)throw new Error('请选择25MB以内的 JPG 或 PNG');const img=await createImageBitmap(file);let blob;try{const scale=Math.min(1,1600/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);blob=await new Promise(resolve=>c.toBlob(resolve,'image/jpeg',.85))}finally{img.close()}if(!blob)throw new Error('图片处理失败');const data=new FormData();data.append('photo',blob,'验证.jpg');await work.post(`/tasks/${a.id}/files`,data)})}
async function removeFile(id){await act(()=>work.delete(`/task-files/${id}`))}
watch(()=>props.focusId,()=>{page.value=1;load()})
onMounted(load)
onBeforeUnmount(()=>{loadSequence++})
</script>

<style scoped>.tasks-panel{display:grid;gap:16px}.tasks-panel header{display:flex;justify-content:space-between;align-items:center;gap:12px}.tasks-panel h2,.tasks-panel h3{margin:0;font-size:18px}.assigned-task,.task-create{background:white;border:1px solid #e0e5ed;border-radius:12px;padding:18px}.tasks-panel form{display:grid;gap:14px;margin-top:14px}.tasks-panel label{display:grid;gap:6px;font-size:14px}.tasks-panel input,.tasks-panel select,.tasks-panel textarea{box-sizing:border-box;width:100%;font:inherit;padding:10px;border:1px solid #cbd3df;border-radius:6px;min-height:44px}.tasks-panel button{min-height:44px;padding:8px 14px;border:1px solid #dce2ea;background:white;border-radius:7px;cursor:pointer}.tasks-panel .primary,.task-filter .active{background:#bd2035;color:white}.task-filter{display:flex;gap:6px;flex-wrap:wrap}.pair{display:grid;grid-template-columns:1fr 1fr;gap:12px}.check{display:inline-flex!important;align-items:center;margin:6px 16px 6px 0}.check input{width:20px;min-height:20px}.instructions{white-space:pre-wrap;line-height:1.6}.late{color:#bd2035}.files{display:flex;gap:12px;flex-wrap:wrap}.files>div{width:100px}.review{display:flex;gap:10px;flex-wrap:wrap;align-items:end;margin-top:14px}.review label{flex:1}.feedback{background:#fff4df;padding:10px}.tasks-panel small{display:block;color:#68768a;margin-top:10px}summary{cursor:pointer;font-weight:600}@media(max-width:700px){.pair{grid-template-columns:1fr}.tasks-panel header{align-items:start}.assigned-task{padding:14px}.review label{flex-basis:100%}}</style>

<style scoped>
.tasks-panel .task-toolbar h2{font-size:16px;margin:0}.toolbar-actions{display:flex;gap:8px}.tasks-panel .toolbar-actions button{min-height:36px;padding:6px 12px;font-size:13px}
.tasks-panel .task-filter{display:flex;gap:4px;padding:4px;background:#eaf0f5;border-radius:9px;align-self:start}
.tasks-panel .task-filter button{flex:1;display:flex;align-items:center;justify-content:center;gap:6px;min-height:36px;padding:6px 10px;background:transparent;border:0;color:#66758a;font-size:13px;white-space:nowrap}
.tasks-panel .task-filter button.active{background:white;color:#b71b31;box-shadow:0 1px 4px #22304714;font-weight:600}.filter-count{font-size:12px;padding:1px 5px;border-radius:5px;background:#dfe6ee;color:#536478}.active .filter-count{background:#fff0f2;color:#b71b31}
.tasks-panel .assigned-task{padding:16px;border-radius:10px}.tasks-panel .assigned-task h3{font-size:15px;line-height:1.5;margin:0}.tasks-panel .assigned-task header{align-items:start}.task-status{flex-shrink:0;padding:3px 8px;border-radius:5px;font-size:12px;background:#f0f3f7;color:#67758a}.task-status.submitted{background:#fff4df;color:#94611a}.task-status.accepted{background:#eaf7f1;color:#22805a}.task-status.returned,.task-status.late{background:#fff0f2;color:#b71b31}
.tasks-panel small{font-size:12px;margin-top:5px}.tasks-panel .instructions{font-size:14px;margin:12px 0;color:#40516a}.files:empty{display:none}.tasks-panel .review{border-top:1px solid #edf0f4;padding-top:10px;margin-top:12px}.deadline-edit summary{list-style:none;font-size:13px;font-weight:400!important;color:#61738d;padding:4px 0!important}.deadline-edit summary::-webkit-details-marker{display:none}.deadline-edit summary:hover{color:#b71b31}.deadline-edit[open] summary{margin-bottom:8px}.deadline-fields{display:flex;gap:8px;align-items:center}.deadline-fields button{white-space:nowrap}.task-create fieldset{border:1px solid #e0e5ed;border-radius:8px}.task-create form{margin-top:0}
@media(max-width:700px){.tasks-panel .task-filter button{padding:6px 4px;gap:4px}.tasks-panel .task-toolbar{align-items:center}.tasks-panel .assigned-task{padding:14px}.tasks-panel .task-filter{gap:2px}}
</style>

<style scoped>.task-result-label{font-size:13px;margin-right:12px}.assigned-task>a{font-size:13px;color:#506b91;text-decoration:none}.assigned-task>a:hover{text-decoration:underline}</style>
